<?php require __DIR__.'/src/bootstrap.php'; ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EXPEDIG</title>
<style>
:root{--navy:#06264b;--blue:#0d5bd7;--line:#dce5ef;--bg:#f4f7fb;--text:#14263f;--muted:#6a788b;--green:#15945b;--red:#c33}*{box-sizing:border-box}body{margin:0;font:14px Segoe UI,Arial,sans-serif;background:var(--bg);color:var(--text)}header{height:72px;background:var(--navy);color:#fff;display:flex;align-items:center;padding:0 22px;gap:24px}.brand{font-size:22px;font-weight:800;min-width:230px}.brand small{display:block;font-size:11px;font-weight:500}.search{flex:1;max-width:760px;position:relative}.search input{width:100%;height:44px;border:0;border-radius:9px;padding:0 14px;font-size:15px}.results{position:absolute;top:49px;left:0;right:0;background:#fff;color:var(--text);border:1px solid var(--line);border-radius:9px;box-shadow:0 14px 35px #001b3a22;display:none;z-index:20;max-height:380px;overflow:auto}.result{padding:12px;border-bottom:1px solid #edf1f5;cursor:pointer}.result:hover{background:#f0f6ff}.layout{display:grid;grid-template-columns:220px 1fr;min-height:calc(100vh - 72px)}aside{background:linear-gradient(#07345f,#052447);padding:14px 10px;color:#fff}.nav{padding:12px 14px;border-radius:8px;margin:5px 0;cursor:pointer}.nav.active,.nav:hover{background:var(--blue)}main{padding:20px}.view{display:none}.view.active{display:block}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.stat,.card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:16px}.stat b{display:block;font-size:28px;margin-top:8px}.muted{color:var(--muted)}h2{margin:0 0 16px}.table{width:100%;border-collapse:collapse;background:#fff}.table th,.table td{padding:10px;border-bottom:1px solid #e8edf3;text-align:left}.table th{font-size:12px;background:#f8fafc}.bar{height:8px;background:#e7edf4;border-radius:10px;overflow:hidden}.bar i{display:block;height:100%;background:var(--green)}.button{border:1px solid var(--line);background:#fff;padding:9px 12px;border-radius:8px;cursor:pointer;font-weight:600}.button.primary{background:var(--blue);border-color:var(--blue);color:#fff}.button.danger{color:#b42318}.toolbar{display:flex;gap:8px;align-items:center;justify-content:space-between;margin-bottom:12px}.toolbar .group{display:flex;gap:8px}.toolbar input,.toolbar select{padding:9px;border:1px solid var(--line);border-radius:7px}.profile{background:#fff;border:1px solid var(--line);border-radius:12px;padding:17px;display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px}.badge{display:inline-block;padding:4px 9px;border-radius:15px;background:#def5e9;color:#087745;font-weight:700;font-size:11px}.recordgrid{display:grid;grid-template-columns:270px minmax(420px,1fr) minmax(360px,42%);gap:12px}.info-row{display:grid;grid-template-columns:100px 1fr;gap:7px;margin:10px 0}.docs{border:1px solid var(--line);border-radius:8px;overflow:hidden}.docrow{display:grid;grid-template-columns:minmax(130px,1fr) 85px minmax(120px,1.3fr) 72px;gap:7px;padding:10px;border-bottom:1px solid #edf1f5;align-items:center;font-size:12px}.doctype{color:#075bc8;font-weight:700;cursor:pointer}.preview{min-height:620px;display:flex;flex-direction:column}.preview iframe{flex:1;width:100%;border:1px solid var(--line);border-radius:7px;min-height:540px}.placeholder{flex:1;display:grid;place-items:center;border:2px dashed var(--line);border-radius:8px;text-align:center;color:var(--muted);padding:20px}.modal{position:fixed;inset:0;background:#00172e88;display:none;align-items:center;justify-content:center;z-index:40}.modal.show{display:flex}.modalbox{background:#fff;width:min(620px,94vw);max-height:92vh;overflow:auto;border-radius:12px;padding:20px}.field{margin:11px 0}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:5px}.field input,.field select,.field textarea{width:100%;padding:9px;border:1px solid var(--line);border-radius:7px}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:10px}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:15px}.notice{padding:10px 12px;border-radius:8px;background:#eef5ff;margin:10px 0}.dangertext{color:#b42318}@media(max-width:1100px){.cards{grid-template-columns:repeat(2,1fr)}.recordgrid{grid-template-columns:250px 1fr}.preview{grid-column:1/-1}}@media(max-width:760px){.layout{display:block}aside{display:none}header{height:auto;flex-wrap:wrap;padding:12px}.brand{min-width:0}.cards{grid-template-columns:1fr 1fr}.recordgrid{display:block}.card{margin-bottom:10px}.twocol{grid-template-columns:1fr}}
</style></head><body>
<header><div class="brand">EXPEDIG<small>EXPEDIENTES DIGITALES · SEGURO PRIVADO</small></div><div class="search"><input id="globalSearch" placeholder="Buscar por posición, cédula, nombre o apellido..." autocomplete="off"><div id="results" class="results"></div></div></header>
<div class="layout"><aside>
<div class="nav active" data-view="dashboard">▦ Dashboard</div><div class="nav" data-view="record">⌕ Buscar expediente</div><div class="nav" data-view="officers">▣ Funcionarios</div><div class="nav" data-view="import">⇩ Importar CSV</div><div class="nav" data-view="directions">⌂ Direcciones / Zonas</div>
</aside><main>
<section id="dashboard" class="view active"><h2>Control de digitalización</h2><div class="cards"><div class="stat">Funcionarios<b id="stOfficers">0</b></div><div class="stat">Con expediente<b id="stDigitized">0</b></div><div class="stat">Pendientes<b id="stPending">0</b></div><div class="stat">PDF digitalizados<b id="stDocuments">0</b></div></div><div class="card"><h3>Avance por Dirección / Zona</h3><table class="table"><thead><tr><th>Dependencia</th><th>Total</th><th>Digitalizados</th><th>Pendientes</th><th>Avance</th></tr></thead><tbody id="dashboardRows"></tbody></table></div></section>
<section id="record" class="view"><div id="recordEmpty" class="card" style="min-height:420px;display:grid;place-items:center;text-align:center"><div><div style="font-size:50px">📁</div><h2>Buscar expediente policial</h2><div class="muted">Use el buscador superior para abrir un expediente.</div></div></div><div id="recordBody" style="display:none"><div class="profile"><div><h2 id="title"></h2><div id="direction" class="muted"></div><div style="margin-top:8px"><span id="status" class="badge"></span></div></div><div><button class="button" onclick="editCurrentOfficer()">Editar datos</button> <button class="button primary" onclick="openUpload()">＋ Digitalizar documento</button></div></div><div class="recordgrid"><div class="card"><h3>RESUMEN</h3><div id="officerInfo"></div><h3>AVANCE DOCUMENTAL</h3><div class="bar"><i id="progressBar" style="width:0%"></i></div><p><b id="progressText">0%</b> de documentos requeridos.</p></div><div class="card"><h3>DOCUMENTOS (<span id="docCount">0</span>)</h3><div id="docs" class="docs"></div></div><div class="card preview"><div class="toolbar"><div><h3 style="margin:0">VISTA PREVIA</h3><b id="previewName">Ningún documento seleccionado</b></div><button id="closePreview" class="button" style="display:none" onclick="clearPreview()">×</button></div><div id="previewPlaceholder" class="placeholder">Presione el <b>tipo de documento</b> para ver el PDF.</div><iframe id="viewer" style="display:none" title="Vista previa PDF"></iframe></div></div></div></section>
<section id="officers" class="view"><div class="toolbar"><h2>Funcionarios</h2><div class="group"><select id="officerDirection"><option value="">Todas las dependencias</option></select><select id="officerStatus"><option value="">Todos los estados</option><option>activo</option><option>inactivo</option><option>jubilado</option><option>trasladado</option></select><input id="officerQ" placeholder="Buscar..."><button class="button primary" onclick="openOfficerModal()">＋ Nuevo</button></div></div><div class="card"><table class="table"><thead><tr><th>Posición</th><th>Rango / Nombre</th><th>Dependencia</th><th>Estado</th><th>Docs</th><th></th></tr></thead><tbody id="officerRows"></tbody></table></div></section>
<section id="import" class="view"><h2>Importación masiva de funcionarios</h2><div class="card" style="max-width:760px"><p>Cargue un archivo <b>CSV UTF-8</b>. Si una posición ya existe, el sistema actualiza sus datos; si no existe, la crea.</p><div class="notice">Encabezados admitidos: <b>position, cedula, rank_name, first_name, last_name, direction, department, status</b></div><p><a href="import-template.csv" download>Descargar plantilla CSV</a></p><form id="importForm"><div class="field"><label>Archivo CSV</label><input type="file" name="file" accept=".csv,text/csv" required></div><button class="button primary">Importar funcionarios</button></form><div id="importResult"></div></div></section>
<section id="directions" class="view"><div class="toolbar"><h2>Direcciones / Zonas</h2><button class="button primary" onclick="openDirectionModal()">＋ Nueva dependencia</button></div><div class="card"><table class="table"><thead><tr><th>Nombre</th><th>Código</th><th></th></tr></thead><tbody id="directionRows"></tbody></table></div></section>
</main></div>

<div id="uploadModal" class="modal"><div class="modalbox"><h2>Digitalizar documento</h2><form id="uploadForm"><input type="hidden" name="officer_id" id="uploadOfficer"><div class="field"><label>Tipo</label><select name="document_type_id" id="documentType" required></select></div><div class="twocol"><div class="field"><label>Fecha</label><input type="date" name="document_date"></div><div class="field"><label>Archivo PDF</label><input type="file" name="file" accept="application/pdf,.pdf" required></div></div><div class="field"><label>Descripción</label><textarea name="description" rows="3"></textarea></div><div class="actions"><button type="button" class="button" onclick="closeModal('uploadModal')">Cancelar</button><button class="button primary">Guardar</button></div></form></div></div>
<div id="officerModal" class="modal"><div class="modalbox"><h2 id="officerModalTitle">Funcionario</h2><form id="officerForm"><input type="hidden" id="officerId"><div class="twocol"><div class="field"><label>Posición *</label><input id="fPosition" required></div><div class="field"><label>Cédula</label><input id="fCedula"></div><div class="field"><label>Rango</label><input id="fRank"></div><div class="field"><label>Estado</label><select id="fStatus"><option>activo</option><option>inactivo</option><option>jubilado</option><option>trasladado</option></select></div><div class="field"><label>Nombre *</label><input id="fFirst" required></div><div class="field"><label>Apellido *</label><input id="fLast" required></div><div class="field"><label>Dirección / Zona</label><select id="fDirection"></select></div><div class="field"><label>Departamento</label><input id="fDepartment"></div></div><div class="actions"><button type="button" class="button" onclick="closeModal('officerModal')">Cancelar</button><button class="button primary">Guardar</button></div></form></div></div>
<div id="directionModal" class="modal"><div class="modalbox"><h2>Dirección / Zona</h2><form id="directionForm"><input type="hidden" id="dirId"><div class="field"><label>Nombre *</label><input id="dirName" required></div><div class="field"><label>Código</label><input id="dirCode"></div><div class="actions"><button type="button" class="button" onclick="closeModal('directionModal')">Cancelar</button><button class="button primary">Guardar</button></div></form></div></div>
<script>
const $=s=>document.querySelector(s);let currentOfficer=null,lookups={directions:[],document_types:[]},searchTimer;
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
async function api(action,opt={}){const r=await fetch('api.php?action='+action,opt);const d=await r.json();if(!r.ok)throw new Error(d.error||'Error');return d}
function showView(id){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));$('#'+id).classList.add('active');document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===id));if(id==='dashboard')loadDashboard();if(id==='officers')loadOfficers();if(id==='directions')renderDirections()}
document.querySelectorAll('.nav').forEach(n=>n.onclick=()=>showView(n.dataset.view));
$('#globalSearch').addEventListener('input',e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>doSearch(e.target.value.trim()),200)});
async function doSearch(q){const box=$('#results');if(!q){box.style.display='none';return}const rows=await api('search&q='+encodeURIComponent(q));box.innerHTML=rows.length?rows.map(x=>`<div class="result" data-id="${x.id}"><b>${esc(x.position)} · ${esc(x.rank_name||'')} ${esc(x.first_name)} ${esc(x.last_name)}</b><br><small>${esc(x.cedula||'Sin cédula')} · ${esc(x.direction||'Sin dependencia')}</small></div>`).join(''):'<div class="result">Sin resultados</div>';box.style.display='block';box.querySelectorAll('[data-id]').forEach(x=>x.onclick=()=>loadOfficer(x.dataset.id))}
async function loadLookups(){lookups=await api('lookups');const opts='<option value="">Sin dependencia</option>'+lookups.directions.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('');$('#fDirection').innerHTML=opts;$('#officerDirection').innerHTML='<option value="">Todas las dependencias</option>'+lookups.directions.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('');renderDirections()}
async function loadDashboard(){const d=await api('dashboard');$('#stOfficers').textContent=d.totals.officers;$('#stDigitized').textContent=d.totals.digitized;$('#stPending').textContent=d.totals.pending;$('#stDocuments').textContent=d.totals.documents;$('#dashboardRows').innerHTML=d.directions.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.total}</td><td>${x.digitized}</td><td>${x.pending}</td><td style="min-width:180px"><div class="bar"><i style="width:${x.percent}%"></i></div><small>${x.percent}%</small></td></tr>`).join('')}
async function loadOfficer(id){$('#results').style.display='none';const d=await api('officer&id='+id);currentOfficer=d;showView('record');$('#recordEmpty').style.display='none';$('#recordBody').style.display='block';const o=d.officer;$('#title').textContent=`${o.position} - ${o.rank_name||''} ${o.first_name} ${o.last_name}`;$('#direction').textContent=o.direction||'Sin dependencia';$('#status').textContent=(o.status||'activo').toUpperCase();$('#officerInfo').innerHTML=info('Posición',o.position)+info('Cédula',o.cedula||'—')+info('Rango',o.rank_name||'—')+info('Nombre',o.first_name+' '+o.last_name)+info('Dirección',o.direction||'—')+info('Departamento',o.department||'—');$('#progressBar').style.width=d.progress.percent+'%';$('#progressText').textContent=d.progress.percent+'%';$('#docCount').textContent=d.documents.length;$('#documentType').innerHTML=d.document_types.map(t=>`<option value="${t.id}">${esc(t.name)}${+t.required_flag?' *':''}</option>`).join('');$('#uploadOfficer').value=o.id;$('#docs').innerHTML=d.documents.length?d.documents.map(x=>`<div class="docrow"><span class="doctype" onclick="preview(${x.id},'${esc(x.document_type)}')">${esc(x.document_type)}</span><span>${esc(x.document_date||'—')}</span><span>${esc(x.description||x.original_name)}</span><span><button class="button" onclick="deleteDoc(${x.id})">🗑</button></span></div>`).join(''):'<div class="muted" style="padding:20px;text-align:center">Sin documentos digitalizados.</div>';clearPreview()}
function info(a,b){return `<div class="info-row"><b>${esc(a)}:</b><span>${esc(b)}</span></div>`}function preview(id,name){$('#previewName').textContent=name;$('#previewPlaceholder').style.display='none';$('#viewer').style.display='block';$('#viewer').src='api.php?action=document&id='+id+'#toolbar=1&navpanes=0';$('#closePreview').style.display='inline-block'}function clearPreview(){$('#viewer').src='about:blank';$('#viewer').style.display='none';$('#previewPlaceholder').style.display='grid';$('#previewName').textContent='Ningún documento seleccionado';$('#closePreview').style.display='none'}
function openUpload(){if(currentOfficer)$('#uploadModal').classList.add('show')}function closeModal(id){$('#'+id).classList.remove('show')}
$('#uploadForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api('upload',{method:'POST',body:new FormData(e.target)});closeModal('uploadModal');e.target.reset();await loadOfficer(currentOfficer.officer.id);await loadDashboard()}catch(x){alert(x.message)}finally{b.disabled=false}};
async function deleteDoc(id){if(!confirm('¿Eliminar este documento digitalizado? Esta acción también eliminará el PDF almacenado.'))return;try{await api('delete_document',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});await loadOfficer(currentOfficer.officer.id);await loadDashboard()}catch(x){alert(x.message)}}
async function loadOfficers(){const q=encodeURIComponent($('#officerQ').value);const dir=$('#officerDirection').value;const st=encodeURIComponent($('#officerStatus').value);const rows=await api(`officers&q=${q}&direction_id=${dir}&status=${st}`);$('#officerRows').innerHTML=rows.map(x=>`<tr><td><b>${esc(x.position)}</b><br><small>${esc(x.cedula||'')}</small></td><td>${esc(x.rank_name||'')} ${esc(x.first_name)} ${esc(x.last_name)}</td><td>${esc(x.direction||'—')}</td><td>${esc(x.status)}</td><td>${x.document_count}</td><td><button class="button" onclick="loadOfficer(${x.id})">Abrir</button> <button class="button" onclick='openOfficerModal(${JSON.stringify(x)})'>Editar</button></td></tr>`).join('')}
['officerDirection','officerStatus'].forEach(id=>$('#'+id).onchange=loadOfficers);$('#officerQ').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(loadOfficers,250)};
function openOfficerModal(o=null){$('#officerForm').reset();$('#officerId').value=o?.id||'';$('#fPosition').value=o?.position||'';$('#fCedula').value=o?.cedula||'';$('#fRank').value=o?.rank_name||'';$('#fFirst').value=o?.first_name||'';$('#fLast').value=o?.last_name||'';$('#fDepartment').value=o?.department||'';$('#fStatus').value=o?.status||'activo';const d=lookups.directions.find(x=>x.name===o?.direction);$('#fDirection').value=d?.id||'';$('#officerModal').classList.add('show')}
function editCurrentOfficer(){if(currentOfficer)openOfficerModal(currentOfficer.officer)}
$('#officerForm').onsubmit=async e=>{e.preventDefault();const payload={id:+$('#officerId').value||0,position:$('#fPosition').value,cedula:$('#fCedula').value,rank_name:$('#fRank').value,first_name:$('#fFirst').value,last_name:$('#fLast').value,direction_id:$('#fDirection').value,department:$('#fDepartment').value,status:$('#fStatus').value};try{const r=await api('save_officer',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});closeModal('officerModal');await loadLookups();await loadOfficers();await loadDashboard();if(currentOfficer&&currentOfficer.officer.id==r.id)await loadOfficer(r.id)}catch(x){alert(x.message)}};
function renderDirections(){$('#directionRows').innerHTML=lookups.directions.map(d=>`<tr><td>${esc(d.name)}</td><td>${esc(d.code||'—')}</td><td><button class="button" onclick='openDirectionModal(${JSON.stringify(d)})'>Editar</button></td></tr>`).join('')}
function openDirectionModal(d=null){$('#directionForm').reset();$('#dirId').value=d?.id||'';$('#dirName').value=d?.name||'';$('#dirCode').value=d?.code||'';$('#directionModal').classList.add('show')}
$('#directionForm').onsubmit=async e=>{e.preventDefault();try{await api('save_direction',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:+$('#dirId').value||0,name:$('#dirName').value,code:$('#dirCode').value})});closeModal('directionModal');await loadLookups();await loadDashboard()}catch(x){alert(x.message)}};
$('#importForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;$('#importResult').innerHTML='Importando...';try{const d=await api('import_officers',{method:'POST',body:new FormData(e.target)});$('#importResult').innerHTML=`<div class="notice"><b>${d.inserted}</b> nuevos · <b>${d.updated}</b> actualizados${d.errors.length?'<br><span class="dangertext">No procesados: '+esc(d.errors.join(', '))+'</span>':''}</div>`;await loadLookups();await loadDashboard()}catch(x){$('#importResult').innerHTML='<p class="dangertext">'+esc(x.message)+'</p>'}finally{b.disabled=false}};
(async()=>{await loadLookups();await loadDashboard()})();
</script></body></html>
